let cwdOpen: string | null = null;
let loadSeq = 0;

/** False when the project could not be shown (error, or unsaved files elsewhere). */
export async function loadFiles(cwd: string): Promise<boolean> {
  files.loading = true;
  files.error = "";
  const my = ++loadSeq;
  try {
    const r = await invoke<FileList>("files_list", { cwd, ignored: settings.filesShowIgnored });
    // A later request (another project) won: this answer is dropped.
    if (my !== loadSeq) return false;
    const sameRoot = r.root === files.root;
    if (!sameRoot && files.root && dirtyTabs().length) {
      toast(t("filesStore.unsavedBeforeSwitch"));
      return false;
    }
    // Large and read-only: not made deeply reactive (50 000 paths).
    Object.assign(files, { root: r.root, git: r.git, list: markRaw(r.files), status: markRaw(r.status), truncated: r.truncated });
    if (!sameRoot) {
      // Another project: unsaved edits are not carried over (the caller asked first).
      files.tabs = [];
      files.active = null;
    };
  });
}

/** Closes the context menu. */
function closeFileMenu() {
  fileMenu.value = null;
  document.removeEventListener("mousedown", onDocumentMouseDown, true);
  document.removeEventListener("keydown", onDocumentKeyDown, true);
}

/** Closes the context menu on a click outside the context menu. */
function onDocumentMouseDown(event: MouseEvent) {
  if (fileMenuElement.value?.contains(event.target as Node) === true) {
    return;
  }
  closeFileMenu();
}

/** Closes the context menu on the key Escape. */
function onDocumentKeyDown(event: KeyboardEvent) {
  if (event.key === "Escape") {
    event.stopPropagation();
    closeFileMenu();
  }
}

/** Puts the absolute path or the relative path of the file of the context menu on the clipboard, and closes the menu. */
async function copyPath(kind: "absolute" | "relative") {
  const relativePath = fileMenu.value?.path ?? null;
  closeFileMenu();
  if (relativePath === null) {
    return;
  }
  let text = relativePath;
  if (kind === "absolute") {
    try {
      text = await invoke<string>("file_full_path", { root: files.root, path: relativePath });
    } catch (error) {
      toast(String(error), "error");
      return;
    }
  }
  await copy(text);
  toast(t("filesPanel.copied", { path: text }));
}

onBeforeUnmount(closeFileMenu);

/** The icon of a row: a folder that is closed or open, or the kind of the file. */
function rowIcon(row: TreeRow): string {
  if (row.dir) {
    return files.expanded.has(row.path) ? "folder2-open" : "folder2";
  }
  return fileIconName(row.name);
}

/** The name of the arrow of a folder row. A file row has no arrow, but it keeps the space of the arrow. */
function arrowIcon(row: TreeRow): string | null {
  if (row.dir === false || row.ignored) {
    return null;
  startRename("ws", workspaceId);
}

/**
 * Asks for a confirmation, then closes a workspace. The question lives in the status bar section and not in the card, because
 * the card closes when the keyboard focus goes to the confirmation dialog. When the setting `confirmWorkspaceClose` is off,
 * the workspace closes at once, without the question.
 *
 * @param workspace - The workspace to close.
 */
async function askClose(workspace: WorkspaceInfo): Promise<void> {
  const isConfirmed =
    settings.confirmWorkspaceClose === false ||
    (await askConfirm(
      t("workspaceStatusSummary.close", { name: workspace.label }),
      t("workspaceStatusSummary.closeConfirm"),
    ));
  if (isConfirmed === true) {
    await closeWorkspace(workspace.workspace_id);
  }
}

/** Asks for the folder of a new workspace, then creates the workspace with the name of the folder. */
async function createWorkspace(): Promise<void> {
  close();
  const path = await openDialog({
    directory: true,
    multiple: false,
    title: t("workspaceStatusSummary.chooseFolder"),
    defaultPath: await homeDir(),
  });
  if (path === null) {
    return;
  }
  const label = path.split("/").filter(Boolean).pop() ?? null;
  await newWorkspace(path, label);
}

// The command search renames the workspace too: the field replaces the name, so the card must not stay open.
watch(isRenaming, (renaming) => {
  if (renaming === true) {
    close();
  }
});
